(* Build two-minus kinematics directly from PLUS freqs P={w3,...,wn}.
   Minus freqs w1,w2 = roots of t^2 + e1 t + e2, e1=Sum P, e2=Sum pairs.
   sigma=(-1,-1,+1,...,+1). k_i = sigma_i w_i^2 / g. *)
MakeTwoMinus[P_List, g_]:=Module[{e1,e2,disc,r,w1,w2,ws,sig,ks},
 e1=Total[P]; e2=Total[Times@@@Subsets[P,{2}]];
 disc=e1^2-4 e2; r=Sqrt[disc];
 w1=(-e1+r)/2; w2=(-e1-r)/2;
 ws=Join[{w1,w2},P];
 sig=Join[{-1,-1},Table[1,Length[P]]];
 ks=sig*ws^2/g;
 {ks,ws}];
(* check against MakeKinematics: take agent's example plus legs {5/2,3,-3} *)
{ks,ws}=MakeTwoMinus[{5/2,3,-3},1];
Print["ws=",ws," sumw=",Total[ws]," summomcheck=",Total[Join[{-1,-1,1,1,1}]*ws^2]];
amp=BGAmplitude[ks,ws,1];
Print["A5/I=",Simplify[amp/I]];
EOF
wolframscript -file fu_kin.wls"}

